EDITS = {'CHANGELOG.md': [('lines 1-1', "## [0.264.0] - Bank Block and Warehouse Yard; a merged building's stairs skinned again\n", '## [0.265.0] - the gameplay-events switch\n\nThe walker: "so we can flip the switch, turn gameplay events on, and then the gameplay layer could ingest if\nwarranted" (the factory\'s roadmap 323).\n\n### Added\n- **`MissionBrief.gameplay_events`** (default `false`) and the authoring panel\'s **Gameplay events** control on every\n  template. On, a score\'s alarm hooks -- Deli Counter 0.289.0\'s `alarm` markers at its teller lines, vault doors,\n  deposit units, drop safes, ATMs and cash carts -- reach Dispatch as `trigger` anchors carrying their event (the\n  marker\'s `meta` and its room, read by Dispatch 0.6.0\'s `anchors.event_block`). Off, they are left out of\n  Dispatch\'s inputs and every package is what it was. Outside the functional signature: an event is data a game may\n  ignore, and changes nothing a lock protects.\n- `packages/staging/dispatch_inputs.py`: `alarm` maps to `trigger`; `EVENT_MARKERS`; `stage_dispatch_inputs(...,\n  events=)`, passed the brief\'s field by the CLI.\n\n### Tests\n- `tests/unit/test_gameplay_events.py` (new; fails on 0.264.0): off, no event reaches the anchors; on, an alarm is a\n  trigger carrying its event and every other anchor is unchanged; the switch is off by default and outside the lock;\n  the panel offers it on every template.\n\n## [0.264.0] - Bank Block and Warehouse Yard; a merged building\'s stairs skinned again\n')], 'VERSION': [('lines 1-1', '0.264.0', '0.265.0')], 'apps/cli/commands/__init__.py': [('lines 1527-1528', '        lot_site=_latest_output(lot_out, "site.site.drawn.json"),\n    )\n', '        lot_site=_latest_output(lot_out, "site.site.drawn.json"),\n        # the score\'s gameplay events, only when the brief turns them on (0.265.0)\n        events=bool(getattr(model, "gameplay_events", False)),\n    )\n')], 'packages/core/models.py': [('lines 145-146', '    roof_props: bool = True\n    seed_policy: str = "derived"\n', '    roof_props: bool = True\n    #: GAMEPLAY EVENTS (0.265.0, the factory\'s roadmap 323). The walker: "so we can flip the switch, turn gameplay\n    #: events on, and then the gameplay layer could ingest if warranted". On, the score\'s alarm hooks Deli Counter\n    #: records (`ALARM_FIXTURES`) reach Dispatch as `trigger` anchors carrying their event; off -- the default -- the\n    #: package is exactly what it was. Not in the functional signature: an event is data a game may ignore, and\n    #: changes nothing a lock protects.\n    gameplay_events: bool = False\n    seed_policy: str = "derived"\n')], 'packages/service/design.py': [('lines 131-132', '         "support": "supported", "consumer": "Zoo\'s rooftop scatter", "rebuilds": "art"},\n        # the standard\'s PLAYERS (0.253.0): one spawn per crew member, and the crew Laser Tag plays\n', '         "support": "supported", "consumer": "Zoo\'s rooftop scatter", "rebuilds": "art"},\n        # the walker: "flip the switch, turn gameplay events on" (0.265.0): data for a gameplay layer, off by default\n        {"key": "gameplay_events", "label": "Gameplay events", "type": "boolean",\n         "default": bool(brief.get("gameplay_events", False)), "support": "supported",\n         "note": "The score\'s alarm and score events -- a teller\'s panic button, a vault door, a deposit box drilled -- "\n                 "sent to Dispatch for a gameplay layer to use or ignore. Off, the level is exactly as before.",\n         "consumer": "Dispatch\'s trigger anchors (packages.staging.dispatch_inputs)", "rebuilds": "export"},\n        # the standard\'s PLAYERS (0.253.0): one spawn per crew member, and the crew Laser Tag plays\n')], 'packages/staging/dispatch_inputs.py': [('lines 37-40', '    "extraction": "extraction", "exit": "extraction", "interactive": "interaction",\n}\n\n\n', '    "extraction": "extraction", "exit": "extraction", "interactive": "interaction",\n    # a score\'s alarm hook (Deli Counter 0.289.0\'s `ALARM_FIXTURES`): a trigger carrying its event (0.265.0)\n    "alarm": "trigger",\n}\n#: The marker types that are GAMEPLAY EVENTS (0.265.0): staged only when the brief turns them on.\nEVENT_MARKERS = ("alarm",)\n\n\n'), ('lines 64-64', 'def markers_to_anchors(gameplay: dict, source: str, up: str = "z") -> list:\n', 'def markers_to_anchors(gameplay: dict, source: str, up: str = "z", events: bool = False) -> list:\n'), ('lines 67-67', '    uniqueness)."""\n', '    uniqueness). A gameplay event\'s marker (`EVENT_MARKERS`) is staged only with\n    ``events`` on, its `meta` the anchor\'s `event` (Dispatch 0.6.0\'s\n    `anchors.event_block`), with its room."""\n'), ('lines 71-72', '        raw_type = str(rec.get("type", ftype) or ftype)\n        atype = _TYPE_MAP.get(raw_type, raw_type)  # pass unknown through\n', '        raw_type = str(rec.get("type", ftype) or ftype)\n        if raw_type in EVENT_MARKERS and not events:\n            continue\n        atype = _TYPE_MAP.get(raw_type, raw_type)  # pass unknown through\n'), ('lines 91-92', '            anchor["building"] = str(rec["building"])\n        anchors.append(anchor)\n', '            anchor["building"] = str(rec["building"])\n        if raw_type in EVENT_MARKERS and isinstance(rec.get("meta"), dict):\n            ev = {k: v for k, v in rec["meta"].items() if k in ("event", "audible", "fixture", "fires", "repeat")}\n            if rec.get("room"):\n                ev["room"] = str(rec["room"])\n            anchor["event"] = ev\n        anchors.append(anchor)\n'), ('lines 242-242', '                          lot_site: Path | None = None) -> dict:\n', '                          lot_site: Path | None = None, events: bool = False) -> dict:\n'), ('lines 271-271', '    dc_anchors = markers_to_anchors(dc_gp, "deli_counter", dc_up)\n', '    dc_anchors = markers_to_anchors(dc_gp, "deli_counter", dc_up, events=events)\n'), ('lines 309-309', '        site_markers_to_anchors(lot_gp, "lot") + markers_to_anchors(lot_gp, "lot", lot_up),\n', '        site_markers_to_anchors(lot_gp, "lot") + markers_to_anchors(lot_gp, "lot", lot_up, events=events),\n')]}
WHOLE = {}
NEW_FILES = {'tests/unit/test_gameplay_events.py': '"""The gameplay-events switch (0.265.0, the factory\'s roadmap 323).\n\nThe walker: "so we can flip the switch, turn gameplay events on, and then the gameplay layer could ingest if\nwarranted". Off -- the default -- a score\'s alarm markers stay out of Dispatch\'s inputs and the package is what it was;\non, each becomes a `trigger` anchor carrying its event for Dispatch 0.6.0\'s `event_block`. FAILS ON 0.264.0.\n"""\nimport sys\nfrom pathlib import Path\n\nROOT = Path(__file__).resolve().parents[2]\nsys.path.insert(0, str(ROOT))\n\nfrom packages.core.models import MissionBrief  # noqa: E402\nfrom packages.service import design  # noqa: E402\nfrom packages.staging.dispatch_inputs import markers_to_anchors  # noqa: E402\n\nGAMEPLAY = {"markers": [\n    {"name": "b0/ALARM_INT_-1_6_OPEN0", "type": "alarm", "id": "int_-1_6_open0", "x": -8.0, "y": -3.0, "z": -1.95,\n     "room": "b0/vault", "building": "b0",\n     "meta": {"event": "alarm.vault_door", "audible": True, "fixture": "vault_door"}},\n    {"name": "b0/OBJECTIVE_A", "type": "objective", "id": "A", "x": -8.0, "y": 5.0, "z": -3.3, "building": "b0"},\n]}\n\n\ndef test_off_the_package_carries_no_event():\n    anchors = markers_to_anchors(GAMEPLAY, "lot")\n    assert [a["type"] for a in anchors] == ["objective"]\n    assert not any("event" in a for a in anchors)\n\n\ndef test_on_an_alarm_is_a_trigger_carrying_its_event():\n    anchors = markers_to_anchors(GAMEPLAY, "lot", events=True)\n    trig, = [a for a in anchors if a["type"] == "trigger"]\n    assert trig["event"] == {"event": "alarm.vault_door", "audible": True, "fixture": "vault_door", "room": "b0/vault"}\n    assert trig["building"] == "b0" and trig["pos"] == [-8.0, -3.0, -1.95]\n    # every other anchor is what it was with the switch off\n    assert [a for a in anchors if a["type"] != "trigger"] == markers_to_anchors(GAMEPLAY, "lot")\n\n\ndef test_the_switch_is_off_by_default_and_outside_the_lock():\n    assert MissionBrief.__dataclass_fields__["gameplay_events"].default is False\n    off = MissionBrief(mission_id="m_001", display_name="M")\n    on = MissionBrief(mission_id="m_001", display_name="M", gameplay_events=True)\n    assert off.functional_signature() == on.functional_signature()\n\n\ndef test_the_panel_offers_it_on_every_template():\n    for tid in design.templates():\n        c = {x["key"]: x for x in design.capabilities(tid)}["gameplay_events"]\n        assert c["type"] == "boolean" and c["default"] is False and c["support"] == "supported"\n'}


def _sha(text):
    return hashlib.sha256(text.encode("utf-8")).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (REPO / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: %s/%s has mixed line endings; nothing written" % (REPO.name, name))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text) != PINS[name]:
        raise SystemExit("REFUSED: %s/%s is %s, not the %s this patch was written against; nothing written"
                         % (REPO.name, name, _sha(text), PINS[name]))
    return text, crlf > 0


def main():
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: %s/%s: the anchor at %s is there %d times; nothing written"
                                 % (REPO.name, name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name, text in WHOLE.items():
        _old, crlf = _read(name)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (REPO / name).exists():
            raise SystemExit("REFUSED: %s/%s exists already; nothing written" % (REPO.name, name))
    for name, text in out.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (REPO / name).parent.mkdir(parents=True, exist_ok=True)
        (REPO / name).write_bytes(text.encode("utf-8"))
    print("%s: %d files edited, %d written" % (REPO.name, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main())
